alter table public.items add column if not exists stats jsonb not null default '{}';
alter table public.items add column if not exists icon text not null default '';
alter table public.items drop constraint if exists items_slot_check;
alter table public.items add constraint items_slot_check check (slot in ('head','body','legs','feet','cape','weapon','offhand','neck','ring','consumable'));
create or replace function public.char_stats(u uuid) returns jsonb language plpgsql security definer set search_path = public as $$ declare lv int; cl text; e jsonb; b jsonb; a int := 0; d int := 0; v int := 0; m int := 0; r record; begin select level, cls into lv, cl from profiles where id = u; select equip into e from characters where user_id = u; lv := coalesce(lv, 1); cl := coalesce(cl, 'Mago'); b := (case cl when 'Guerreiro' then '{"atk":8,"def":6,"vit":120,"mana":10}' when 'Mago' then '{"atk":3,"def":3,"vit":80,"mana":60}' when 'Ladino' then '{"atk":6,"def":3,"vit":90,"mana":20}' when 'Arqueiro' then '{"atk":7,"def":3,"vit":90,"mana":20}' when 'Clérigo' then '{"atk":3,"def":5,"vit":100,"mana":50}' else '{"atk":4,"def":4,"vit":100,"mana":20}' end)::jsonb; for r in select i.stats from items i where i.slot <> 'consumable' and i.id in (select value from jsonb_each_text(coalesce(e, '{}'::jsonb))) and exists (select 1 from inventory v2 where v2.user_id = u and v2.item_id = i.id) loop a := a + coalesce((r.stats->>'atk')::int, 0); d := d + coalesce((r.stats->>'def')::int, 0); v := v + coalesce((r.stats->>'vit')::int, 0); m := m + coalesce((r.stats->>'mana')::int, 0); end loop; return jsonb_build_object('base', jsonb_build_object('atk', (b->>'atk')::int + (lv - 1), 'def', (b->>'def')::int + (lv - 1) / 2, 'vit', (b->>'vit')::int + (lv - 1) * 10, 'mana', (b->>'mana')::int + (lv - 1) * 2), 'bonus', jsonb_build_object('atk', a, 'def', d, 'vit', v, 'mana', m), 'total', jsonb_build_object('atk', (b->>'atk')::int + (lv - 1) + a, 'def', (b->>'def')::int + (lv - 1) / 2 + d, 'vit', (b->>'vit')::int + (lv - 1) * 10 + v, 'mana', (b->>'mana')::int + (lv - 1) * 2 + m)); end $$;
revoke execute on function public.char_stats(uuid) from public, anon, authenticated;
create or replace function public.my_character() returns jsonb language plpgsql security definer set search_path = public as $$ declare c characters%rowtype; begin if auth.uid() is null then raise exception 'login necessário'; end if; insert into characters (user_id) values (auth.uid()) on conflict do nothing; select * into c from characters where user_id = auth.uid(); return jsonb_build_object('skin', c.skin, 'hair', c.hair, 'hair_color', c.hair_color, 'equip', c.equip, 'starter', c.starter, 'inv', coalesce((select jsonb_agg(item_id order by acquired_at) from inventory where user_id = auth.uid()), '[]'::jsonb), 'stats', char_stats(auth.uid())); end $$;
create or replace function public.equip_item(iid text) returns jsonb language plpgsql security definer set search_path = public as $$ declare s text; begin select slot into s from items where id = iid; if s is null then raise exception 'item inexistente'; end if; if s = 'consumable' then raise exception 'este item não é equipável'; end if; if not exists (select 1 from inventory where user_id = auth.uid() and item_id = iid) then raise exception 'você não possui este item'; end if; perform my_character(); update characters set equip = equip || jsonb_build_object(s, iid), updated_at = now() where user_id = auth.uid(); return my_character(); end $$;
